previewCss:
.darma-loader-light-bulb-flicker {
  position: relative;
  width: 34px;
  height: 52px;
}
.darma-loader-light-bulb-flicker::before {
  content: "";
  position: absolute;
  top: 2px;
  left: 50%;
  width: 30px;
  height: 30px;
  margin-left: -15px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
  box-shadow: 0 0 12px 2px var(--loader-color, #6366f1);
  animation: darma-loader-light-bulb-flicker-glow 1.2s ease-in-out infinite;
}
.darma-loader-light-bulb-flicker i {
  position: absolute;
  top: 31px;
  left: 50%;
  width: 14px;
  height: 13px;
  margin-left: -7px;
  border-radius: 0 0 3px 3px;
  background: #4338ca;
}
.darma-loader-light-bulb-flicker i::before {
  content: "";
  position: absolute;
  top: 3px;
  left: 1px;
  right: 1px;
  height: 1px;
  background: #312e81;
  box-shadow: 0 4px 0 #312e81, 0 8px 0 #312e81;
}
@keyframes darma-loader-light-bulb-flicker-glow {
  0%, 100% { opacity: 1; }
  45% { opacity: 0.32; }
  55% { opacity: 0.9; }
}

